# AUTOGENERATED KERNEL (LLM)
# Source: LLM-generated candidate implementation
# Status: Experimental / uncurated
# Expectation: Correctness-first, performance not representative

import torch
import torch.nn as nn
import triton
import triton.language as tl


def get_kl_div_configs():
    configs = [
        triton.Config(
            {"BLOCK_SIZE": 32},
        )
    ]
    return configs


@triton.autotune(
    configs=get_kl_div_configs(),
    key=["n_cols"],
)
@triton.jit
def kl_div_row_kernel(
    pred_ptr,
    target_ptr,
    out_ptr,
    n_cols,
    stride_pred_row,
    stride_target_row,
    BLOCK_SIZE: tl.constexpr,
):
    row_idx = tl.program_id(0)
    pred_row_start = pred_ptr + row_idx * stride_pred_row
    target_row_start = target_ptr + row_idx * stride_target_row

    acc = 0.0

    for col_start in tl.range(0, n_cols, BLOCK_SIZE):
        col_offsets = col_start + tl.arange(0, BLOCK_SIZE)
        mask = col_offsets < n_cols

        pred_vals = tl.load(pred_row_start + col_offsets, mask=mask, other=1.0).to(
            tl.float32
        )
        target_vals = tl.load(target_row_start + col_offsets, mask=mask, other=0.0).to(
            tl.float32
        )

        kl_vals = tl.where(
            target_vals > 0, target_vals * tl.log(target_vals / pred_vals), 0.0
        )
        acc += tl.sum(kl_vals, axis=0)

    tl.store(out_ptr + row_idx, acc)


def kernel_function(predictions: torch.Tensor, targets: torch.Tensor) -> torch.Tensor:
    assert predictions.is_contiguous() and targets.is_contiguous()
    B, N = predictions.shape

    row_sums = torch.empty(B, device=predictions.device, dtype=torch.float32)

    grid = (B,)
    kl_div_row_kernel[grid](
        predictions,
        targets,
        row_sums,
        N,
        predictions.stride(0),
        targets.stride(0),
    )

    return row_sums.sum() / B


class Model(nn.Module):
    def __init__(self):
        super(Model, self).__init__()

    def forward(self, predictions, targets):
        return kernel_function(predictions, targets)
